const oxfordSceneImages=["oxford_radcliffe_camera.png","oxford_bodleian_library.png","oxford_bridge_of_sighs.png","oxford_christ_church.png","oxford_university_church.png","oxford_river_cherwell.png"];
function renderOxfordTalk(){document.querySelector(".oxford-play")?.remove();const p=oxfordMissions[oxfordSelected];if(!p)return;const branches=oxfordTalks[oxfordSelected];let text=oxfordDialogueStep===0?p.intro:oxfordDialogueStep===1?branches[oxfordDialogueBranch][1]:branches[oxfordDialogueBranch][3];const options=oxfordDialogueStep===0?branches.map((v,i)=>'<button data-oxford-branch="'+i+'">'+esc(v[0])+'</button>').join(''):oxfordDialogueStep===1?'<button data-oxford-follow="1">'+esc(branches[oxfordDialogueBranch][2])+'</button><button data-oxford-start-quiz="1">Thanks! Start the challenge →</button>':'<button data-oxford-start-quiz="1">Start the challenge →</button><button data-oxford-restart="1">↺ Ask another question</button>';const question=oxfordPhase==="quiz"?'<strong>🎯 '+esc(p.task)+'</strong><div class="oxford-talk-options">'+p.choices.map((v,i)=>'<button data-oxford-talk-answer="'+i+'">'+esc(v)+'</button>').join('')+'</div>':oxfordPhase==="done"?'<strong>🏅 '+esc(p.stamp)+'</strong><p>'+esc(p.fact)+'</p><button data-oxford-collect="1">'+(oxfordDone().includes(oxfordSelected)?'Back to Oxford map':'Collect discovery · +20 miles')+'</button>':'<div class="oxford-talk-speaker"><span class="oxford-talk-avatar-wrap"><img class="oxford-talk-avatar" src="assets/portraits/'+oxfordPortraitImages[oxfordSelected]+'?v=oxford-portraits-39" alt="Portrait of '+esc(p.guide)+'"></span><div><strong>'+esc(p.guide)+'</strong><p>'+esc(text)+'</p></div></div><div class="oxford-talk-options">'+options+'</div><small>Conversation '+(oxfordDialogueStep+1)+'/3 · Choose what to say</small>';const el=document.createElement("div");el.className="oxford-play";el.setAttribute("role","dialog");el.setAttribute("aria-modal","true");el.setAttribute("aria-label",p.name);el.innerHTML='<style>.oxford-play{position:fixed;inset:0;z-index:99999;background:#071729d9;display:flex;align-items:center;justify-content:center;padding:14px}.oxford-play-panel{width:min(1100px,100%);max-height:96dvh;overflow:auto;background:#fff1cf;color:#462d20;border:3px solid #d49d49;border-radius:17px;padding:clamp(10px,2vw,20px);box-shadow:0 16px 55px #0007}.oxford-talk-layout{display:grid;grid-template-columns:minmax(0,1.08fr) minmax(0,1fr);gap:15px;align-items:start}.oxford-talk-scene{position:relative;min-height:310px;border:2px solid #d7b071;border-radius:9px;background:#fff1cf;overflow:hidden;aspect-ratio:16/10;min-height:0}.oxford-talk-scene img{display:block;width:100%;height:100%;object-fit:contain;object-position:center}.oxford-talk-box{background:#fffaf0;color:#462d20;border:2px solid #c28a43;border-radius:12px;padding:14px;min-width:0}.oxford-talk-speaker{display:flex;gap:12px;align-items:flex-start;min-width:0}.oxford-talk-speaker>div:last-child{min-width:0;flex:1}.oxford-talk-avatar-wrap{display:block;width:126px;flex:0 0 126px;align-self:flex-start;background:transparent;border:0;padding:0;overflow:visible}.oxford-talk-avatar{display:block;width:100%;height:auto;max-width:100%!important;object-fit:contain;position:static;background:transparent!important;border:0!important;box-shadow:none!important;outline:0!important;padding:0!important;margin:0!important;border-radius:0!important}.oxford-talk-speaker{background:transparent;border:0;box-shadow:none;align-items:flex-start}.oxford-talk-speaker>div:last-child{min-width:0;flex:1}@media(max-width:680px){.oxford-talk-avatar-wrap{width:104px;flex-basis:104px}}@media(max-width:380px){.oxford-talk-avatar-wrap{width:86px;flex-basis:86px}}.oxford-talk-options{display:flex;flex-direction:column;gap:9px;margin-top:16px}.oxford-talk-options button,.oxford-play button{cursor:pointer;border:2px solid #9c6028;background:linear-gradient(#fff2c4,#ffd680);color:#3b2618;border-radius:8px;padding:10px;font-weight:800}.oxford-talk-options button:hover,.oxford-play button:hover{filter:brightness(1.08)}.oxford-talk-options button{width:100%;text-align:left;padding:13px 15px}.oxford-play-panel h2{margin:0 0 9px;color:#67351d}.oxford-play-panel p{color:#513725}.oxford-talk-box strong{color:#79421b}.oxford-play-actions button{background:linear-gradient(#ffe4a1,#ecb454)}.oxford-play-actions{display:flex;justify-content:space-between;gap:10px;margin-top:16px;flex-wrap:wrap}@media(max-width:680px){.oxford-talk-layout{grid-template-columns:1fr}.oxford-talk-scene{min-height:150px}.oxford-talk-box{padding:12px}}</style><div class="oxford-play-panel"><div style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap"><h2>📍 '+esc(p.name)+'</h2><strong style="color:#88511c">💬 INTERACTIVE DIALOGUE · '+(oxfordDialogueStep+1)+'/3</strong></div><div class="oxford-talk-layout"><div class="oxford-talk-scene"><img src="assets/oxford/'+oxfordSceneImages[oxfordSelected]+'?v=oxford-scenes-35" alt="Illustration of '+esc(p.name)+'"></div><div class="oxford-talk-box"><p style="font-weight:900;color:#8d4a1c">🗣️ TALK TO A LOCAL · CHOOSE YOUR REPLY ↓</p><div style="background:#fff1cf;border:1px solid #d7b071;border-radius:10px;padding:12px">'+question+'</div></div></div><div class="oxford-play-actions"><button data-oxford-previous="1">← Previous place</button><button data-oxford-close="1">Back to map</button><button data-oxford-next="1">Next place →</button></div><p>'+oxfordDone().length+'/6 discoveries · '+state.miles+' Explorer Miles</p></div>';document.body.append(el);el.querySelector("[data-oxford-close]")?.focus()}
document.addEventListener("click",e=>{const b=e.target.closest(".oxford-play button");if(!b)return;if(b.dataset.oxfordClose){document.querySelector(".oxford-play")?.remove();oxfordSelected=-1;renderOxford();return}if(b.dataset.oxfordPrevious){openOxfordTalk((oxfordSelected+5)%6);return}if(b.dataset.oxfordNext){openOxfordTalk((oxfordSelected+1)%6);return}if(b.dataset.oxfordBranch!==undefined){oxfordDialogueBranch=Number(b.dataset.oxfordBranch);oxfordDialogueStep=1}else if(b.dataset.oxfordFollow){oxfordDialogueStep=2}else if(b.dataset.oxfordRestart){oxfordDialogueStep=0}else if(b.dataset.oxfordStartQuiz){oxfordPhase="quiz"}else if(b.dataset.oxfordTalkAnswer!==undefined){const n=Number(b.dataset.oxfordTalkAnswer);if(n===oxfordMissions[oxfordSelected].correct){oxfordPhase="done"}else{notify("Try again! Talk to the guide and choose another answer.");return}}else if(b.dataset.oxfordCollect){oxfordComplete(oxfordSelected);document.querySelector(".oxford-play")?.remove();oxfordSelected=-1;renderOxford();return}else return;renderOxfordTalk()});
const oxfordStampImages=["stamp-radcliffe.png","stamp-bodleian.png","stamp-bridge.png","stamp-christchurch.png","stamp-church.png","stamp-cherwell.png"];
