function oxfordPassportHTML(done){const cards=[['explorer-miles.webp','Explorer Miles',state.miles+' total miles'],['completed-missions.webp','Completed missions',done.length+'/6 Oxford places'],['discoveries.webp','Discoveries',done.length+'/6 landmarks'],['country-facts.webp','Passport stamps',done.length+'/6 collected']];return '<div class="oxford-passport-panel"><h2>📘 Pixel Passport</h2><p>Your Oxford travel record and England country identity, in one place.</p><div class="oxford-passport-tabs"><button data-oxford-passport-view="journey" class="'+(oxfordPassportView==='journey'?'selected':'')+'">⭐ My Journey</button><button data-oxford-passport-view="identity" class="'+(oxfordPassportView==='identity'?'selected':'')+'">🪪 England · Country ID</button></div>'+(oxfordPassportView==='journey'?'<div class="oxford-passport-cards">'+cards.map(c=>'<article><img src="assets/passport-badges/'+c[0]+'" alt=""><h3>'+c[1]+'</h3><p>'+c[2]+'</p></article>').join('')+'</div><h3>🏅 Oxford stamps</h3><div class="oxford-passport-grid">'+oxfordMissions.map((m,i)=>'<span class="oxford-stamp-tile '+(done.includes(i)?'is-earned':'is-locked')+'"><img src="assets/oxford/'+oxfordStampImages[i]+'" alt="" loading="lazy"><strong>'+esc(m.stamp)+'</strong><small>'+(done.includes(i)?'✓ Collected':'🔒 Locked')+'</small></span>').join('')+'</div>':'<div class="oxford-passport-cards"><article><h3>🏴 Country</h3><p>England · United Kingdom</p></article><article><h3>🏙️ Capital</h3><p>London</p></article><article><h3>🗣️ Language</h3><p>English</p></article><article><h3>💷 Currency</h3><p>Pound sterling (£)</p></article></div><p>England’s country identity is shared across London and Oxford.</p>')+'</div>'}
document.addEventListener('click',e=>{const b=e.target.closest('[data-oxford-passport-view]');if(!b)return;oxfordPassportView=b.dataset.oxfordPassportView==='identity'?'identity':'journey';renderOxford();const target=document.querySelector('.oxford-passport-panel');target?.scrollIntoView({block:'start',behavior:'instant'})});
let oxfordSelected=-1,oxfordAnswer=null;
const oxfordDone=()=>Array.isArray(state.oxfordCompleted)?state.oxfordCompleted:[];
function oxfordComplete(i){if(oxfordDone().includes(i))return;state.oxfordCompleted=[...oxfordDone(),i];state.miles+=20;save();notify("Oxford discovery unlocked · +20 miles")}
